def transform(grid):
    """Extend each numbered point along its color-specific path; collisions spawn a 4 ray."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two right, then one up; the terminal point repeats color 1.
                cells = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
            elif color == 2:
                # Four left.
                cells = [(r, c - k) for k in range(5)]
            elif color == 3:
                # Three down.
                cells = [(r + k, c) for k in range(4)]
            elif color == 6:
                # Six up.
                cells = [(r - k, c) for k in range(7)]
            else:
                continue
            valid = [(rr, cc) for rr, cc in cells if 0 <= rr < h and 0 <= cc < w]
            paths.append((color, (r, c), valid))

    owners = {}
    for i, (color, source, cells) in enumerate(paths):
        for pos in cells:
            owners.setdefault(pos, []).append(i)

    collisions = []
    for pos, ids in owners.items():
        r, c = pos
        if len(ids) > 1:
            out[r][c] = 4
            collisions.append(pos)
        else:
            color, source, cells = paths[ids[0]]
            if pos == source:
                out[r][c] = color
            elif pos == cells[-1]:
                out[r][c] = color
            else:
                out[r][c] = 5

    # Each 4 collision extends diagonally down-left to the canvas edge.
    for r, c in collisions:
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
